mapper.insert:
INSERT INTO TB_ALARM_CHECK (ALARM_ID, USER_ID, CHECKED_AT)
SELECT A.ALARM_ID, CAST(#{userId} AS VARCHAR), CURRENT_TIMESTAMP
FROM TB_ALARM A
LEFT JOIN TB_USER U ON U.USER_ID = #{userId}
WHERE (U.CREATED_AT IS NULL OR A.OCCURRED_AT >= U.CREATED_AT)
  AND NOT EXISTS (
    SELECT 1 FROM TB_ALARM_CHECK C
    WHERE C.ALARM_ID = A.ALARM_ID AND C.USER_ID = #{userId}
)
ON CONFLICT (ALARM_ID, USER_ID) DO NOTHING
